contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We expose a single test function that attempts a withdrawal and asserts
    // that only the owner can make the contract's balance become zero by withdrawal.
    // Parameters:
    // - caller: the address that will call withdrawAll (simulated via tx.origin/msg.sender in the test harness)
    // - recipient: address to receive funds
    // - fundAmount: amount of wei that this test contract will forward to C before withdrawal

    // Note: the verifier/harness must arrange that this function is invoked with msg.sender == caller.
    function runTest(address caller, address payable recipient, uint256 fundAmount) public payable {
        // require this test contract has enough balance to fund c
        require(address(this).balance >= fundAmount);

        // Fund the target contract c by calling its fallback with value
        // This is a state-changing call on c and must be top-level
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        // Record c's balance before withdrawal via observable address(c).balance
        uint256 before = address(c).balance;

        // Ensure there is something to withdraw; otherwise the test is vacuous
        require(before > 0);

        // Now perform the withdrawal call as the provided caller. The harness should call this
        // function such that msg.sender == caller. This single state-changing call drives the deciding behavior.
        c.withdrawAll(recipient);

        // After withdrawal, observe the contract balance
        uint256 after = address(c).balance;

        // Assert: only the owner can make the balance go to zero. That is, if the caller is not the owner,
        // the balance must remain unchanged (withdraw should not transfer funds). This distinguishes P from M.
        // We express this as: if caller != c.owner(), then after == before.
        assert( (msg.sender == c.owner()) || (after == before) );
    }

    // Allow this test contract to receive ETH so it can forward funds in the test
    receive() external payable {}
}

