    function run() public payable {
        // No precondition needed: rule should hold for any caller
        bool reverted; try c.withdrawAll(address(0x1234)) { reverted = false; } catch { reverted = true; }
        // In the original contract only the owner can withdraw, so unless this test contract is the owner the call must revert.
        // Express that: if this contract is not the owner, the call reverts.
        assert((address(this) == c.owner()) || reverted);
    }
