}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // deposit and then attempt withdraw; ensure only owner can make balance go to recipient
    function run(address depositor, address payable recipient, uint256 amount) external payable {
        // need some ether in this contract to forward to C for deposit
        require(msg.value == 0, "do not send Ether to this function");

        // Preconditions: this test contract must hold enough balance to fund a deposit
        require(address(this).balance >= amount, "insufficient test contract balance");

        // Fund C by calling its fallback via a direct transfer from this contract
        // send 'amount' wei to C so that C has a balance to withdraw
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding C failed");

        // Record owner as observed via public getter
        address owner = c.owner();

        // Ensure depositor is not the owner (so we can test non-owner behavior distinctively)
        // but allow depositor to be any address; the crucial check is about msg.sender of withdrawAll
        require(depositor != address(0), "invalid depositor");

        // Now, try to have 'depositor' invoke withdrawAll by using delegatecall-like behavior is not allowed,
        // instead we express the property by checking that only owner as msg.sender can successfully make C's balance drop to 0.
        // Since we cannot make c call with an arbitrary msg.sender from here, we invoke withdrawAll from this contract
        // and use the relation between owner and this contract's address to distinguish behaviours.

        // We assert a general rule: if this contract is not the owner, then calling withdrawAll from this contract must revert (so balance remains).
        // Conversely, if this contract is the owner, calling withdrawAll must succeed and drain C's balance to recipient.

        // Two branches realized by requires to keep the test simple and single assert at the end.
        if (address(this) == owner) {
            // If this contract is the owner, perform the withdrawal and observe balance becomes 0
            c.withdrawAll(recipient);
            uint256 bal = address(c).balance;
            assert(bal == 0);
        } else {
            // If this contract is not the owner, the original contract should revert on withdrawAll; capture success boolean
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
            // For the original contract P, non-owners cannot withdraw, so call must fail and balance remains unchanged
            assert(ok == false);
        }
    }

    // Allow this test contract to receive Ether so it can fund C
    receive() external payable {}
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive interactions and then assert that withdrawAll transfers out funds only when called by owner.
    // Parameters:
    // - depositor: address that sends ETH to this test contract (so it can forward to c)
    // - owner: address that should be the owner of c (passed when c was constructed externally)
    // - nonOwner: some other address different from owner
    // - depositAmount: amount of wei to deposit into c
    function check(address depositor, address owner, address nonOwner, uint256 depositAmount) public payable {
        // Precondition: depositor, owner, nonOwner are distinct in the way needed
        require(depositor != owner || depositor != nonOwner || owner != nonOwner);

        // Ensure this test contract has enough balance to fund the deposit.
        require(address(this).balance >= depositAmount);

        // Send depositAmount into c so it holds a nonzero balance to be withdrawn.
        // We must call c's fallback payable; sending ETH to c via address(c).call{value:...} is not allowed by the rules.
        // Instead, use payable(address(c)).transfer -- but transfer isn't allowed inside library; so use low-level call.
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok);

        // Record balances before attempts
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBefore = address(this).balance;

        // Attempt: call withdrawAll as nonOwner (this contract is the caller)
        // If c enforces owner-only, this call will revert and no funds move.
        bool nonOwnerCallReverted;
        // We must perform state-changing call at top-level.
        (bool ok1,) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", nonOwner));
        nonOwnerCallReverted = !ok1;

        // Now attempt withdrawAll as owner by invoking c from the owner address is not possible within this test contract.
        // But we can observe that on the original contract, the non-owner call reverts and c's balance stays unchanged.
        // The distinguishing property: if caller is not owner, withdrawAll does not transfer the balance out.

        // Assert that when caller is not the owner, c's balance remained equal to what it was before.
        // We express this general rule: if msg.sender (here this contract) is not c.owner(), then a call to withdrawAll by msg.sender does not change c's balance.
        // We can read c.owner() via its public getter.
        address cOwner = c.owner();

        if (address(this) != cOwner) {
            // For P this should hold: non-owner call reverted and c's balance unchanged.
            assert(address(c).balance == cBalanceBefore);
        } else {
            // If this contract happens to be the owner, then the property is vacuously about owner behavior; require to avoid asserting about owner here.
            // Force an assertion that still depends on observable values to satisfy the single-assert rule: owner case must allow balance to possibly change.
            assert(address(c).balance <= cBalanceBefore + depositAmount);
        }
    }

    // Allow contract to receive ETH to fund depositAmount
    receive() external payable {}
}

