    function run(address caller, address payable recipient) public payable {
        require(caller != address(0));
        bool reverted;
        // simulate call from `caller` by using low-level call to c.withdrawAll
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        // The above call originates from this contract, not `caller`. To model different msg.sender,
        // we instead require that when msg.sender != c.owner(), the original contract would revert.
        // We can observe owner via the public getter.
        address owner = c.owner();
        // We captured whether the attempted withdraw (from this test contract) reverted.
        reverted = !ok;
        // General rule: if the caller is not the owner then withdrawAll must revert.
        // Here `caller` is the hypothetical caller; we assert that for any caller != owner, the call would revert.
        // To connect these, require that `caller` is different from this contract so we don't confuse origins.
        assert((caller == owner) == (!reverted));
    }
    receive() external payable { }
}

