    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        bool reverted;
        // make the call from this contract; caller is the msg.sender simulated by passing as argument
        // We cannot change msg.sender, so instead we treat `caller` as the EOA that would call withdrawAll.
        // To observe the security property without changing msg.sender, we characterize it as: if caller != c.owner(), then calling withdrawAll should revert.
        // Since we cannot impersonate, we use the fact that withdrawAll reverts when msg.sender != owner in the original.
        // Call withdrawAll with `caller` as the recipient and observe whether the call reverted.
        try c.withdrawAll(caller) { reverted = false; } catch { reverted = true; }
        // General rule: if the recipient address is not equal to the contract's owner getter, then the call must have reverted.
        // We can observe owner via c.owner().
        assert((address(c.owner()) == caller) || reverted);
    }
    receive() external payable { }
}

