pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: the caller who will attempt withdrawal and an amount of ETH seeded into c.
    // General rule: only the owner (address(this)) can withdraw funds. For all inputs, when a non-owner
    // tries withdrawAll, the contract balance must remain equal to the pre-call balance (reference enforces this),
    // whereas the mutant removing the require will allow some non-owner to drain funds.
    function testFuzz_property(address caller, uint128 seedAmount) public {
        // keep seedAmount in a reasonable wide range but allow zero as well
        uint256 amount = uint256(seedAmount) % 1 ether; // bound to < 1 ether for test economy

        // fund the contract from an external EOA
        vm.deal(address(this), amount);
        if (amount > 0) {
            // send Ether to c so there's a balance to withdraw
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent);
        }

        uint256 before = address(c).balance;

        // If caller is the owner (address(this)), withdraw should succeed and balance becomes 0.
        // If caller is not the owner, reference contract will revert or prevent transfer, leaving balance unchanged.
        // We simulate the external caller using vm.prank to set msg.sender.
        bool ok;
        vm.prank(caller);
        try c.withdrawAll(address(0xBEEF)) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // Single assertion: if the caller is not the owner, the contract balance must remain unchanged.
        // This is a universal property the reference satisfies for ALL inputs; the mutant removing the require
        // will allow some non-owner caller to make after < before, causing this assertion to fail for those inputs.
        if (caller != address(this)) {
            assertTrue(after == before);
        } else {
            // owner may withdraw, so after must be <= before; in reference it will be 0 when amount>0
            assertTrue(after <= before);
        }
    }
}
